int najdluzszaPodtablicaBrute(int[] tab, int k) {
    int najlepsza = 0;
    for (int i = 0; i < tab.length; i++) {
        int suma = 0;
        for (int j = i; j < tab.length; j++) {
            suma += tab[j];
            if (suma == k) {
                najlepsza = Math.max(najlepsza, j - i + 1);
            }
        }
    }
    return najlepsza;
}
// O(n^2) - dziala poprawnie, ale nieoptymalnie. ZAWSZE miej to jako plan awaryjny.

int najdluzszaPodtablicaOptymalna(int[] tab, int k) {
    Map<Integer, Integer> pierwszyIndeksSumy = new HashMap<>();
    pierwszyIndeksSumy.put(0, -1); // suma 0 'wystapila' przed poczatkiem tablicy
    int biezacaSuma = 0, najlepsza = 0;
    for (int i = 0; i < tab.length; i++) {
        biezacaSuma += tab[i];
        if (pierwszyIndeksSumy.containsKey(biezacaSuma - k)) {
            najlepsza = Math.max(najlepsza, i - pierwszyIndeksSumy.get(biezacaSuma - k));
        }
        pierwszyIndeksSumy.putIfAbsent(biezacaSuma, i); // TYLKO pierwsze wystapienie danej sumy
    }
    return najlepsza;
}
// test: [1,-1,5,-2,3], k=3 -> wynik 4 (podtablica [1,-1,5,-2] sumuje sie do 3)

// BLEDNIE (brakujace zalozenie: ten sam element uzyty dwukrotnie)
int[] dwaSumujaSie_BLAD(int[] tab, int target) {
    for (int i = 0; i < tab.length; i++) {
        int potrzebne = target - tab[i];
        for (int j = 0; j < tab.length; j++) {
            if (tab[j] == potrzebne) return new int[]{i, j}; // BRAK sprawdzenia i != j!
        }
    }
    return new int[]{-1, -1};
}
// dla tab=[3], target=6: zwroci [0,0] - ten sam element uzyty DWUKROTNIE, mimo ze zadanie
// (przy doprecyzowaniu w fazie ZROZUM) mogloby wymagac DWOCH ROZNYCH elementow

// POPRAWNIE: zalozenie 'i != j' jest JAWNE, bo zostalo ustalone w fazie ZROZUM
int[] dwaSumujaSie_OK(int[] tab, int target) {
    Map<Integer, Integer> widziane = new HashMap<>(); // wartosc -> indeks (wzorzec z lekcji 5)
    for (int i = 0; i < tab.length; i++) {
        int potrzebne = target - tab[i];
        if (widziane.containsKey(potrzebne)) {
            return new int[]{widziane.get(potrzebne), i}; // dwa ROZNE indeksy z definicji
        }
        widziane.put(tab[i], i);
    }
    return new int[]{-1, -1};
}
// dodatkowa korzysc: przy okazji O(n) zamiast O(n^2) - hashmap eliminuje petle zagniezdzona

